import numpy as np

def heuristic(dist_m, turn_deg, swath_len_m, energy_left_frac, depot_dist_m, fits):
    total_trip = dist_m + swath_len_m + depot_dist_m
    transit_cost = np.log(total_trip / (depot_dist_m + 1.0))
    turn_rad = np.radians(turn_deg)
    turn_cost = 2 * turn_rad / np.pi

    energy_limit = 0.25
    if energy_left_frac <= energy_limit:
        safety_term = -np.log(energy_left_frac / (1.0 - energy_limit + 0.001))
    else:
        safety_term = -2.0 * (energy_left_frac - energy_limit) ** 2

    normalized_dist = transit_cost + turn_cost
    return np.exp(-normalized_dist) * np.maximum(0.0, 1.0 + safety_term)
